import{_ as o,C as t,o as s,c as i,E as a,a2 as d}from"./chunks/framework.VWKgVqrc.js";const l="/joinwell52/assets/handoff-turn-20261116/turn-boundary.en.svg",b=JSON.parse(`{"title":"The ticket was escalated. Why did the AI answer about shipping?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The ticket was escalated. Why did the AI answer about shipping?","date":"2026-11-16","published_date":"2026-11-16","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Can queued input replace a forced final tool result in the same turn?","summary":"A tool says the ticket was escalated just as the user asks about an order. In a bounded AG2 before/after comparison, one extra model call replaces the handoff result with a shipping answer. We compare that turn boundary with CodeFlowMu's delivery evidence.","cover":"/assets/handoff-turn-20261116/handoff-turn.cover.png","language":"en-US","lifecycle":"Published","publication_authorized":true,"evidence_status":"AG2 v1.3.2 function-level comparison and three upstream regressions; controlled CodeFlowMu native delivery probe; no live model or end-to-end Host run","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-11-16-handoff-new-message.md","filePath":"en/research/2026-11-16-handoff-new-message.md","lastUpdated":1794798965000}`),h={name:"en/research/2026-11-16-handoff-new-message.md"};function u(c,e,p,m,f,g){const r=t("ArticleCover"),n=t("ArticleTableScroll");return s(),i("div",null,[a(r,{image:"/assets/handoff-turn-20261116/handoff-turn.cover.png",kicker:"Engineering research · Agent handoff",title:"The ticket was escalated. Why did the AI answer about shipping?",summary:"A tool says the ticket was escalated just as the user asks about an order. In a bounded AG2 before/after comparison, one extra model call replaces the handoff result with a shipping answer. We compare that turn boundary with CodeFlowMu's delivery evidence.",version:"2026-11-16",languageHref:"/zh/research/2026-11-16-handoff-new-message",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-ticket-was-escalated-why-did-the-ai-answer-about-shipping" tabindex="-1">The ticket was escalated. Why did the AI answer about shipping? <a class="header-anchor" href="#the-ticket-was-escalated-why-did-the-ai-answer-about-shipping" aria-label="Permalink to &quot;The ticket was escalated. Why did the AI answer about shipping?&quot;">​</a></h1><p>A user says, “I need a person.” The AI calls a tool, which returns “Ticket escalated.” Almost at the same moment, the user asks, “What about my order?”</p><p>If the AI immediately handles the follow-up before ending the turn, its final answer may become “Your order shipped.” The handoff happened, but its result has been replaced by a second answer. To the user, the promised human handoff seems to have disappeared. To the next worker, the last sentence no longer says clearly what the previous turn accomplished.</p><p>That is the boundary addressed by <a href="https://github.com/ag2ai/ag2/pull/3639" target="_blank" rel="noreferrer">AG2 contributor coder-abu&#39;s PR #3639</a>. AG2 is an agent development framework. Here, a tool can require its result to end the turn, or hand the call to a client for completion. Before the fix, AG2 skipped its normal tool loop but still drained input queued during the turn and called the model once more. The extra response replaced the final tool result. During a client handoff, the model could even continue before the client&#39;s tool result came back. The fix returns the forced result first and leaves queued input for the next turn <strong>on the same stream</strong>.</p><h2 id="turn-almost-simultaneous-into-a-repeatable-test" tabindex="-1">Turn “almost simultaneous” into a repeatable test <a class="header-anchor" href="#turn-almost-simultaneous-into-a-repeatable-test" aria-label="Permalink to &quot;Turn “almost simultaneous” into a repeatable test&quot;">​</a></h2><p>We pinned AG2 v1.3.2 and used its scripted model and event subscription. The first request asks for a person. A final tool returns <code>Ticket escalated.</code> When the tool result arrives, the test queues <code>What about my order?</code>; the scripted model has <code>Your order shipped.</code> ready as an answer. These strings are test data, not a real order status.</p><p>To isolate what changed, we inserted only the pre-fix <code>_execute_turn</code> function body into the rest of the current runtime, then compared it with the current function:</p><table tabindex="0"><thead><tr><th>Same interleaving point</th><th>Final reply for this turn</th><th style="text-align:right;">Model calls in this turn</th></tr></thead><tbody><tr><td>Pre-fix loop body with the current remaining runtime</td><td><code>Your order shipped.</code></td><td style="text-align:right;">2</td></tr><tr><td>Current v1.3.2 loop body</td><td><code>Ticket escalated.</code></td><td style="text-align:right;">1</td></tr></tbody></table><p><img src="'+l+'" alt="The old loop lets queued input replace the handoff result; the current loop preserves it for this turn"></p><p>We also ran three relevant AG2 regression tests: retaining a final tool result, resuming a client handoff after its tool result, and consuming ordinary mid-turn input in the current turn. All three passed. The “pre-fix” row is a <strong>function-level causal comparison</strong>, not a full run of an old release or a live model provider. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-16-turn-boundary/00-report.en.md" target="_blank" rel="noreferrer">public experiment script, pinned versions, and results</a> make that limit explicit.</p><p>The fix does not mean every new message must wait. Ordinary tools may still consume input during the current turn if the model is continuing. The important distinction is that <strong>once a tool has ended the turn or handed control to a client, a follow-up must not silently reopen that result.</strong> AG2&#39;s PR also notes that adapters creating a fresh stream for every request need a separate answer about where queued input lives.</p><h2 id="compare-our-multi-agent-system" tabindex="-1">Compare our multi-agent system <a class="header-anchor" href="#compare-our-multi-agent-system" aria-label="Permalink to &quot;Compare our multi-agent system&quot;">​</a></h2><p>CodeFlowMu is our local multi-agent collaboration system. It too can send a person&#39;s new instruction to a running worker, but it does not implement AG2&#39;s stream. Our comparison therefore asks a more basic question: <strong>was a message saved, delivered to the native process, or consumed by the model in this turn?</strong></p><p>Our local probe crossed CodeFlowMu&#39;s actual native delivery method. If the process had already ended, it returned <code>not_live</code> and wrote nothing to the process. If the process ended during a write without a native delivery receipt, it returned <code>unknown</code> and saved the input. Looking up the same request again retained <code>unknown</code>, with no second write. Twenty-seven relevant coordination and delivery regressions passed. Two full integration cases stopped at the prerequisite for a trusted administrator test environment; <strong>we did not count them as passing</strong>.</p><p>These observations show that the tested local boundary does not equate “saved” with “the model received it.” They do not establish how every live Host assigns a turn at the handoff instant, or make a chat follow-up into a newly authorized formal task. FCoP records formal task, report, and acceptance facts across employees. A Host&#39;s conversation turn is a separate boundary. They need to be linked, not used as evidence for each other.</p><h2 id="the-next-question" tabindex="-1">The next question <a class="header-anchor" href="#the-next-question" aria-label="Permalink to &quot;The next question&quot;">​</a></h2><p>This research did not confirm a CodeFlowMu product defect or produce a development review item. The next valuable experiment is to send a follow-up <strong>during work, at handoff, and after process exit</strong> on the same real Host, then compare the final reply, native delivery receipt, model-call count, and any new execution attempt. Without that evidence, AG2&#39;s fix is not a CodeFlowMu ticket.</p><p>For engineers designing multi-agent work, the case raises a genuine choice: when a worker has already produced a handoff result, should new input wait for the next turn on the same stream, require redelivery, or start a separate session? Products may choose different experiences. They still need to show the user <strong>what the previous turn delivered, where the new message went, and who is allowed to continue</strong>.</p><p>Our AG2 comparison used a pinned version, scripted model, and one substituted function. The CodeFlowMu comparison used a controlled child-process stand-in. The <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/manual-runs/2026-11-16-turn-boundary/00-report.en.md" target="_blank" rel="noreferrer">English experiment record</a> lists versions, the public rerun probe, and the limits of the restricted product evidence.</p>',19))])}const y=o(h,[["render",u]]);export{b as __pageData,y as default};
